/** Server authoritative encounters. No fake player records and no nested runtime dependencies. */
public final class WorldBossMod implements ModInitializer {
 private static final boolean QA="1".equals(System.getenv("SVFRAME_RUNTIME_QA"));public static final String TAG="svframe_worldboss";private static final Logger LOG=LoggerFactory.getLogger("SVFrameWorldBoss");
 private final java.nio.file.Path directory=FabricLoader.getInstance().getConfigDir().resolve("svframeworldboss");
 private BossConfig config;private BossConfig.Manager configManager;private BossLedger ledger;private BossSchedule schedule;private MinecraftServer server;private long lastSecond=-1,visualTicks;private boolean spawning;
 private final Map<String,Live> live=new LinkedHashMap<>();private final Map<UUID,Float> previousHealth=new HashMap<>();private final Set<String> delivering=new HashSet<>(),warnings=new HashSet<>();
 private static final class Live {final Encounter e;final BossConfig.Boss boss;final BossConfig.Arena arena;final ServerWorld world;final ServerBossBar bar;MobEntity actor;CosmicEncounter cosmic;boolean forced;long nextAttack,impactAt,lastStrike;int phase=1;String lastStage="";UUID target;Vec3d telegraph;
  Live(Encounter e,BossConfig.Boss b,BossConfig.Arena a,ServerWorld w){this.e=e;boss=b;arena=a;world=w;bar=new ServerBossBar(Text.literal(b.name),BossBar.Color.valueOf(b.bossBarColor),BossBar.Style.PROGRESS);}
  Vec3d center(){return new Vec3d(arena.x,arena.y,arena.z);}
 }
 @Override public void onInitialize(){
  InfinityRuntime.install();
  ServerLifecycleEvents.SERVER_STARTED.register(this::startServer);
  ServerLifecycleEvents.SERVER_STOPPING.register(s->{for(var l:List.copyOf(live.values()))abort(l,"server stopping");save();server=null;});
  ServerTickEvents.END_SERVER_TICK.register(s->{if(server==null)return;for(var l:List.copyOf(live.values()))if(l.cosmic!=null&&l.e.state==Encounter.State.FIGHT)l.cosmic.tick();long now=Instant.now().getEpochSecond();if(QA)for(var l:List.copyOf(live.values()))if(l.actor!=null&&l.e.state==Encounter.State.FIGHT){String stage=String.valueOf(attackStatus(l,now).get("stage"));if(!stage.equals(l.lastStage)){l.lastStage=stage;audit(stage,l,null,0);}}if(++visualTicks%4==0)for(var l:List.copyOf(live.values()))if(l.boss.type.equals("pokemon")&&l.impactAt>now&&l.actor!=null&&l.actor.isAlive())warningRing(l);if(now==lastSecond)return;lastSecond=now;try{tick(now);}catch(Exception ex){LOG.error("World boss tick failed; encounter state retained",ex);}});
  ServerEntityEvents.ENTITY_LOAD.register((entity,w)->{if(entity.getCommandTags().contains("svframe_cosmic_minion")&&!CosmicEncounter.MINIONS.contains(entity.getUuid())){entity.discard();return;}if(spawning||!entity.getCommandTags().contains(TAG))return;boolean valid=live.values().stream().anyMatch(l->l.e.actor!=null&&l.e.actor.equals(entity.getUuidAsString()));if(!valid)entity.discard();});
  ServerLivingEntityEvents.ALLOW_DAMAGE.register((entity,source,amount)->{var l=find(entity);if(l==null){if(QA&&find(source.getAttacker())!=null)previousHealth.put(entity.getUuid(),entity.getHealth());return true;}if(l.e.state!=Encounter.State.FIGHT||l.cosmic!=null&&l.cosmic.shielded())return false;previousHealth.put(entity.getUuid(),entity.getHealth());return true;});
  ServerLivingEntityEvents.AFTER_DAMAGE.register((entity,source,base,amount,blocked)->{var l=find(entity);if(l==null){var boss=find(source.getAttacker());var hp=previousHealth.remove(entity.getUuid());if(QA&&boss!=null&&hp!=null)audit("DAMAGE",boss,entity,Math.max(0,hp-entity.getHealth()));return;}var before=previousHealth.remove(entity.getUuid());if(before!=null)credit(l,source.getAttacker(),source.getSource(),Math.max(0,before-entity.getHealth()));});
  ServerLivingEntityEvents.AFTER_DEATH.register((entity,source)->{var l=find(entity);if(l==null){var hp=previousHealth.remove(entity.getUuid());var boss=find(source.getAttacker());if(QA&&boss!=null&&hp!=null)audit("DAMAGE",boss,entity,hp);return;}var before=previousHealth.remove(entity.getUuid());if(before!=null)credit(l,source.getAttacker(),source.getSource(),before);finish(l,true);});
  ServerPlayConnectionEvents.JOIN.register((handler,sender,s)->s.execute(()->{if(ledger!=null)deliver(handler.player);}));
  CommandRegistrationCallback.EVENT.register((dispatcher,access,environment)->dispatcher.register(literal("worldboss")
   .executes(c->info(c.getSource()))
   .then(literal("info").executes(c->info(c.getSource())))
   .then(literal("top").executes(c->{for(var l:live.values()){c.getSource().sendFeedback(()->Text.literal(l.boss.name+" contribution:"),false);l.e.contributions.entrySet().stream().sorted((a,b)->Double.compare(b.getValue().damage,a.getValue().damage)).limit(10).forEach(v->c.getSource().sendFeedback(()->Text.literal(name(v.getKey())+": "+Math.round(v.getValue().damage)+" damage, "+v.getValue().seconds+"s"),false));}return 1;}))
   .then(literal("claim").executes(c->{deliver(c.getSource().getPlayerOrThrow());return 1;}))
   .then(literal("mailbox").executes(c->{var p=c.getSource().getPlayerOrThrow();int pending=ledger.pending(p.getUuid()).stream().mapToInt(r->r.amount).sum();p.sendMessage(Text.literal("Class Sigil mailbox: "+pending+" pending. Use /worldboss claim."),false);return pending;}))
   .then(literal("join").then(argument("arena",word()).executes(c->{var a=config.arena(getString(c,"arena"));var w=world(a);var p=c.getSource().getPlayerOrThrow();var pos=BlockPos.ofFloored(a.x,a.y,a.z);if(!w.getBlockState(pos.down()).isSolidBlock(w,pos.down())||!w.getBlockState(pos).isAir()||!w.getBlockState(pos.up()).isAir())throw new IllegalStateException("Arena entry is blocked");p.teleport(w,a.x,a.y,a.z,Set.of(),p.getYaw(),p.getPitch());return 1;})))
   .then(literal("setarena").requires(s->s.hasPermissionLevel(2)).then(argument("arena",word()).executes(c->setArena(c.getSource(),getString(c,"arena"),32)).then(argument("radius",doubleArg(8,128)).executes(c->setArena(c.getSource(),getString(c,"arena"),getDouble(c,"radius"))))))
   .then(literal("start").requires(s->s.hasPermissionLevel(2)).then(argument("boss",word()).then(argument("arena",word()).executes(c->{begin(getString(c,"boss"),getString(c,"arena"),config.schedule.setupSeconds);return 1;}))))
   .then(literal("abort").requires(s->s.hasPermissionLevel(2)).executes(c->{for(var l:List.copyOf(live.values()))abort(l,"admin abort");return 1;}))
   .then(literal("test").requires(s->s.hasPermissionLevel(2)).then(literal("start").then(argument("boss",word()).then(argument("arena",word()).executes(c->{begin(getString(c,"boss"),getString(c,"arena"),0);return 1;})))).then(literal("win").executes(c->{for(var l:List.copyOf(live.values()))finish(l,true);return 1;})).then(literal("loss").executes(c->{for(var l:List.copyOf(live.values()))finish(l,false);return 1;})))
   .then(literal("reload").requires(s->s.hasPermissionLevel(2)).executes(c->{if(!live.isEmpty()){c.getSource().sendError(Text.literal("Abort active encounters before reload"));return 0;}try{var next=configManager.reload();var nextSchedule=new BossSchedule(next.schedule.timezone,next.scheduleTimes());config=next;schedule=nextSchedule;c.getSource().sendFeedback(()->Text.literal("World boss configuration reloaded: "+config.bosses.bosses.size()+" bosses."),true);return 1;}catch(java.io.IOException|IllegalArgumentException ex){c.getSource().sendError(Text.literal("World boss reload rejected; working configuration retained. "+ex.getMessage()));return 0;}}))));
 }
 private void startServer(MinecraftServer s){try{configManager=new BossConfig.Manager(directory,this::validateClass,this::validatePokemon);config=configManager.current();ledger=BossLedger.load(directory.resolve("state.json"));schedule=new BossSchedule(config.schedule.timezone,config.scheduleTimes());server=s;ledger.recover();for(var e:ledger.encounters.values())if(e.forcedChunk){try{var a=config.arena(e.arena);var pos=BlockPos.ofFloored(a.x,a.y,a.z);world(a).setChunkForced(pos.getX()>>4,pos.getZ()>>4,false);}catch(Exception ex){LOG.warn("Could not release recovered arena chunk {}",e.arena,ex);}e.forcedChunk=false;}save();for(var w:s.getWorlds())for(var entity:w.iterateEntities())if(entity.getCommandTags().contains(TAG))entity.discard();for(var p:s.getPlayerManager().getPlayerList())deliver(p);LOG.info("World boss ready: {} arenas; zone {}",config.locations.locations.size(),config.schedule.timezone);}catch(Exception ex){server=null;throw new IllegalStateException("Could not initialize world boss config/ledger",ex);}}
 private ServerWorld world(BossConfig.Arena arena){var world=server.getWorld(RegistryKey.of(RegistryKeys.WORLD,Identifier.of(arena.dimension)));if(world==null)throw new IllegalArgumentException("Unknown dimension "+arena.dimension);return world;}
 private int setArena(net.minecraft.server.command.ServerCommandSource source,String id,double radius)throws com.mojang.brigadier.exceptions.CommandSyntaxException {if(!id.matches("[a-z0-9_-]{1,48}"))throw new IllegalArgumentException("Invalid arena id");var p=source.getPlayerOrThrow();var pos=p.getBlockPos();var w=p.getServerWorld();if(!w.getBlockState(pos.down()).isSolidBlock(w,pos.down())||!w.getBlockState(pos).isAir()||!w.getBlockState(pos.up()).isAir())throw new IllegalArgumentException("Stand on a solid floor with two blocks of air");if(live.containsKey(id))throw new IllegalStateException("Arena in use");config.locations.locations.removeIf(a->a.id.equals(id));config.locations.locations.add(new BossConfig.Arena(id,w.getRegistryKey().getValue().toString(),p.getX(),p.getY(),p.getZ(),radius));try{config.saveLocations();}catch(java.io.IOException ex){throw new IllegalStateException(ex);}source.sendFeedback(()->Text.literal("Arena "+id+" saved, radius "+radius+". No terrain changed."),true);return 1;}
 private void begin(String bossId,String arenaId,int setup){if(server==null)throw new IllegalStateException("World boss unavailable");if(live.containsKey(arenaId))throw new IllegalStateException("Arena already has an encounter");var b=config.boss(bossId);var a=config.arena(arenaId);var w=world(a);var pos=BlockPos.ofFloored(a.x,a.y,a.z);if(!w.getBlockState(pos.down()).isSolidBlock(w,pos.down())||!w.getBlockState(pos).isAir()||!w.getBlockState(pos.up()).isAir())throw new IllegalStateException("Arena spawn needs a solid floor and air");if(b.type.equals("pokemon")){var factory=NativeMobFactories.get("cobblemon:pokemon");if(factory==null)throw new IllegalStateException("Native Cobblemon integration is required");factory.validate(pokemonProperties(b));}
  long now=Instant.now().getEpochSecond();var e=new Encounter(UUID.randomUUID().toString(),b.id,a.id,now,b.health,setup,config.schedule.fightSeconds);var l=new Live(e,b,a,w);ledger.encounters.put(e.id,e);save();live.put(a.id,l);int x=pos.getX()>>4,z=pos.getZ()>>4;l.forced=!w.getForcedChunks().contains(ChunkPos.toLong(x,z));e.forcedChunk=l.forced;save();if(l.forced)w.setChunkForced(x,z,true);broadcast(b.name+" arrives at "+a.id+" in "+setup+"s. /worldboss join "+a.id);}
 private void tick(long now){
  for(var slot:schedule.upcoming(Instant.ofEpochSecond(now),config.schedule.warningsSeconds.stream().mapToInt(Integer::intValue).max().orElse(0)))for(int lead:config.schedule.warningsSeconds){long delta=slot.toEpochSecond()-now;var key=slot+":"+lead;if(delta<=lead&&delta>lead-2&&warnings.add(key))broadcast("World boss in "+lead+"s ("+config.schedule.timezone+").");}
  for(String occurrence:schedule.due(Instant.ofEpochSecond(now),ledger.occurrences)){ledger.occurrences.add(occurrence);int rotation=ledger.rotation++;save();String time=ZonedDateTime.parse(occurrence).toLocalTime().toString();for(var assignment:config.assignments(time,rotation)){if(live.containsKey(assignment.arena()))continue;try{begin(assignment.boss(),assignment.arena(),config.schedule.setupSeconds);}catch(Exception ex){LOG.error("Scheduled boss skipped at {}",assignment.arena(),ex);}}}
  for(var l:List.copyOf(live.values())){
   for(var p:server.getPlayerManager().getPlayerList())if(inArena(l,p)){l.bar.addPlayer(p);if(l.e.state==Encounter.State.FIGHT&&l.e.contributions.containsKey(p.getUuid())&&l.e.contributions.get(p.getUuid()).damage>0&&p.isAlive()&&!p.isCreative()&&!p.isSpectator())l.e.presence(p.getUuid(),1);}else l.bar.removePlayer(p);
   if(l.e.state==Encounter.State.SETUP){l.bar.setName(Text.literal(l.boss.name+" | setup "+Math.max(0,l.e.fightAt-now)+"s"));if(l.e.fight(now)){try{spawn(l);save();broadcast(l.boss.name+" fight started!");}catch(Exception ex){LOG.error("Boss actor spawn failed",ex);abort(l,"actor spawn failed");}}continue;}
   if(l.e.expired(now)){finish(l,false);continue;}if(l.actor==null||!l.actor.isAlive()){abort(l,"actor missing");continue;}
   double ratio=l.actor.getHealth()/l.actor.getMaxHealth();int phase=l.boss.phase(ratio);if(phase!=l.phase){l.phase=phase;if(l.boss.type.equals("class"))configureClass(l.actor,l.boss,ratio);}l.bar.setPercent((float)MathHelper.clamp(ratio,0,1));l.bar.setName(Text.literal(l.boss.name+" | phase "+phase+" | "+Math.round(l.actor.getHealth())+" HP | "+Math.max(0,l.e.deadline-now)+"s"));
   if(l.actor.squaredDistanceTo(l.center())>l.arena.radius*l.arena.radius){l.actor.refreshPositionAndAngles(l.center(),l.actor.getYaw(),0);l.actor.getNavigation().stop();l.target=null;l.impactAt=0;}
   if(l.boss.type.equals("pokemon"))pokemonTick(l,now,phase);var status=attackStatus(l,now);l.bar.setName(Text.literal(l.boss.name+" | phase "+phase+" | "+Math.round(l.actor.getHealth())+" HP | "+status.get("stage")+" "+(status.get("remainingTicks") instanceof Number n?(long)Math.ceil(n.doubleValue()/20):0)+"s | "+Math.max(0,l.e.deadline-now)+"s"));
  }
  if(now%10==0){save();for(var p:server.getPlayerManager().getPlayerList())deliver(p);}
 }
 private void spawn(Live l){MobEntity actor;if(l.boss.type.equals("cosmic")&&l.boss.classId.equals("GAUNTLET_TRIAL")){spawning=true;try{actor=vn.svframe.fantasyhub.core.hero.HeroNpcCombat.spawn(l.world,l.center(),"THOR",l.boss.name,l.boss.health);}finally{spawning=false;}l.cosmic=new CosmicEncounter(actor,l.boss,l.arena);}else if(l.boss.type.equals("cosmic")){var e=vn.svframe.fantasyhub.protocol.Protocol.heroNpcType.create(l.world);if(e==null)throw new IllegalStateException("Cosmic actor missing");e.hero(l.boss.classId);if(l.boss.classId.equals("THANOS"))e.equipStack(net.minecraft.entity.EquipmentSlot.MAINHAND,new net.minecraft.item.ItemStack(vn.svframe.fantasyhub.protocol.Protocol.infinityItems.get("gauntlet")));e.refreshPositionAndAngles(l.center().x,l.center().y,l.center().z,0,0);e.getAttributeInstance(EntityAttributes.GENERIC_MAX_HEALTH).setBaseValue(l.boss.health);e.setHealth((float)l.boss.health);actor=e;l.cosmic=new CosmicEncounter(actor,l.boss,l.arena);}else if(l.boss.type.equals("class"))actor=spawnClass(l);else{actor=NativeMobFactories.get("cobblemon:pokemon").create(l.world,pokemonProperties(l.boss));actor.refreshPositionAndAngles(l.center(),0,0);actor.setAiDisabled(false);protectPokemon(actor);actor.getAttributeInstance(EntityAttributes.GENERIC_MAX_HEALTH).setBaseValue(l.boss.health);actor.setHealth((float)l.boss.health);var scale=actor.getAttributeInstance(EntityAttributes.GENERIC_SCALE);if(scale!=null)scale.setBaseValue(l.boss.scale);}
  var scale=actor.getAttributeInstance(EntityAttributes.GENERIC_SCALE);if(scale!=null)scale.setBaseValue(l.boss.scale);actor.addCommandTag(TAG);InfinityRuntime.mitigation.put(actor.getUuid(),l.boss.damageMitigation);actor.addCommandTag("svframe_encounter:"+l.e.id);actor.setPersistent();for(var slot:net.minecraft.entity.EquipmentSlot.values())actor.setEquipmentDropChance(slot,-1);actor.setCustomName(Text.literal(l.boss.name));actor.setCustomNameVisible(true);actor.setInvulnerable(false);l.actor=actor;l.e.actor=actor.getUuidAsString();if(!l.world.isSpaceEmpty(actor))throw new IllegalStateException("Boss does not fit arena spawn");if(l.world.getEntity(actor.getUuid())==null&&!l.world.spawnEntity(actor))throw new IllegalStateException("Boss spawn refused");l.nextAttack=Instant.now().getEpochSecond()+2;}
 @SuppressWarnings("unchecked")
 private void protectPokemon(MobEntity actor){try{var key=(net.minecraft.entity.data.TrackedData<Boolean>)actor.getClass().getMethod("getUNBATTLEABLE").invoke(null);actor.getDataTracker().set(key,true);}catch(ReflectiveOperationException ex){throw new IllegalStateException("Native Pokemon battle protection unavailable",ex);}}
 private String pokemonProperties(BossConfig.Boss b){return b.properties+" uncatchable=true unbattleable=true";}
 private void validateClass(String classId,List<String> skills){try{Class.forName("vn.svframe.fantasyhub.core.hero.HeroNpcCombat").getMethod("configureTiming",MobEntity.class,int.class,int.class,int.class);Class.forName("vn.svframe.fantasyhub.core.hero.HeroNpcCombat").getMethod("validate",String.class,List.class).invoke(null,classId,skills);}catch(ReflectiveOperationException ex){throw new IllegalArgumentException(ex.getCause()==null?"Native class validation unavailable":ex.getCause().getMessage(),ex);}}
 private void validatePokemon(String properties){var factory=NativeMobFactories.get("cobblemon:pokemon");if(factory==null)throw new IllegalArgumentException("Native Cobblemon integration is required");factory.validate(properties+" uncatchable=true unbattleable=true");}
 private void configureClass(MobEntity actor,BossConfig.Boss boss,double ratio){try{Class.forName("vn.svframe.fantasyhub.core.hero.HeroNpcCombat").getMethod("configure",MobEntity.class,List.class,double.class,double.class).invoke(null,actor,boss.rotation(ratio),boss.cooldown(ratio),boss.damage(ratio));Class.forName("vn.svframe.fantasyhub.core.hero.HeroNpcCombat").getMethod("configureTiming",MobEntity.class,int.class,int.class,int.class).invoke(null,actor,boss.windupSeconds*20,boss.attackSeconds*20,Integer.parseInt(boss.telegraphColor,16));}catch(ReflectiveOperationException ex){throw new IllegalArgumentException("Boss "+boss.id+" native skill configuration failed: "+(ex.getCause()==null?ex.getMessage():ex.getCause().getMessage()),ex);}}
 private MobEntity spawnClass(Live l){spawning=true;try{var api=Class.forName("vn.svframe.fantasyhub.core.hero.HeroNpcCombat");var actor=(MobEntity)api.getMethod("spawn",ServerWorld.class,Vec3d.class,String.class,String.class,double.class).invoke(null,l.world,l.center(),l.boss.classId,l.boss.name,l.boss.health);return ActorCreation.finish(actor,created->{try{api.getMethod("setArena",MobEntity.class,Vec3d.class,double.class).invoke(null,created,l.center(),l.arena.radius);configureClass(created,l.boss,1);}catch(ReflectiveOperationException ex){throw new IllegalStateException("Native class actor arena configuration failed",ex);}},MobEntity::discard);}catch(ReflectiveOperationException ex){throw new IllegalStateException("Native class actor adapter unavailable",ex);}finally{spawning=false;}}
 private void warningRing(Live l){
  if(l.telegraph==null)return;int c=Integer.parseInt(l.boss.telegraphColor,16);var dust=new net.minecraft.particle.DustParticleEffect(new org.joml.Vector3f((c>>16&255)/255f,(c>>8&255)/255f,(c&255)/255f),1.3f);
  for(int i=0;i<56;i++){double a=i*Math.PI/28;l.world.spawnParticles(dust,l.telegraph.x+Math.cos(a)*4,l.telegraph.y+.12,l.telegraph.z+Math.sin(a)*4,1,0,0,0,0);}
 }
 private void pokemonTick(Live l,long now,int phase){
  if(l.impactAt>0&&now>=l.impactAt){
   l.impactAt=0;l.lastStrike=now;l.world.spawnParticles(net.minecraft.particle.ParticleTypes.POOF,l.telegraph.x,l.telegraph.y+.2,l.telegraph.z,24,.7,.1,.7,.03);
   try{var api=Class.forName("vn.svframe.svframemmo.cobblemon.gameplay.PokemonOverworldCombat");for(var p:server.getPlayerManager().getPlayerList())if(inArena(l,p)&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.squaredDistanceTo(l.telegraph)<=16)api.getMethod("strike",MobEntity.class,ServerPlayerEntity.class,double.class).invoke(null,l.actor,p,l.boss.damage(l.actor.getHealth()/l.actor.getMaxHealth()));}
   catch(ReflectiveOperationException ex){LOG.error("Native Pokemon overworld strike unavailable; aborting encounter",ex);abort(l,"native combat adapter unavailable");return;}
   l.nextAttack=now+Math.max(1,(long)Math.ceil(l.boss.attackSeconds*l.boss.cooldown(l.actor.getHealth()/l.actor.getMaxHealth())));
  }
  if(now<l.nextAttack||l.impactAt>0)return;var p=server.getPlayerManager().getPlayerList().stream().filter(v->inArena(l,v)&&v.isAlive()&&!v.isCreative()&&!v.isSpectator()).min(Comparator.comparingDouble(l.actor::squaredDistanceTo)).orElse(null);if(p==null)return;
  l.target=p.getUuid();l.telegraph=p.getPos();l.actor.getLookControl().lookAt(p,30,30);l.actor.getNavigation().startMovingTo(p,1.1);l.impactAt=now+l.boss.windupSeconds;warningRing(l);
  try{Class.forName("vn.svframe.svframemmo.cobblemon.gameplay.PokemonOverworldCombat").getMethod("telegraph",MobEntity.class,ServerPlayerEntity.class).invoke(null,l.actor,p);}catch(ReflectiveOperationException ex){abort(l,"native telegraph adapter unavailable");LOG.error("Native Pokemon telegraph unavailable",ex);return;}
  p.sendMessage(Text.literal(l.boss.name+" charges a strike — leave the marked circle!"),true);
 }
 private Map<?,?> attackStatus(Live l,long now){
  if(l.cosmic!=null)return l.cosmic.status();
  if(l.boss.type.equals("class")&&l.actor!=null)try{return (Map<?,?>)Class.forName("vn.svframe.fantasyhub.core.hero.HeroNpcCombat").getMethod("status",MobEntity.class).invoke(null,l.actor);}catch(ReflectiveOperationException ex){return Map.of("stage","UNAVAILABLE");}
  String stage=l.impactAt>now?"WINDUP":l.lastStrike==now?"ATTACK":now<l.nextAttack?"RECOVERY":"READY";return Map.of("stage",stage,"remainingTicks",Math.max(0,(l.impactAt>now?l.impactAt:l.nextAttack)-now)*20,"point",l.telegraph==null?List.of():List.of(l.telegraph.x,l.telegraph.y,l.telegraph.z),"radius",4);
 }
 private boolean inArena(Live l,ServerPlayerEntity p){return p.getServerWorld()==l.world&&p.squaredDistanceTo(l.center())<=l.arena.radius*l.arena.radius;}
 private Live find(Entity entity){return live.values().stream().filter(l->l.actor==entity).findFirst().orElse(null);}
 private UUID owner(Entity actor){if(actor instanceof ServerPlayerEntity p)return p.isCreative()||p.isSpectator()?null:p.getUuid();if(actor instanceof ProjectileEntity p)return owner(p.getOwner());if(actor instanceof TameableEntity t)return t.getOwnerUuid();if(actor instanceof LivingEntity living){var adapter=RpgEntityAdapters.find(living);if(adapter!=null){var value=adapter.describe(living).get("owner");try{return UUID.fromString(String.valueOf(value));}catch(IllegalArgumentException ignored){}}}return null;}
 private void credit(Live l,Entity attacker,Entity direct,double damage){if(l.e.state!=Encounter.State.FIGHT)return;var id=owner(attacker);if(id==null)id=owner(direct);if(id==null)return;var player=server.getPlayerManager().getPlayer(id);if(player==null||!inArena(l,player)||player.isCreative()||player.isSpectator())return;l.e.damage(id,damage,Instant.now().getEpochSecond());if(l.cosmic!=null)l.cosmic.credit(id,damage);}
 private void finish(Live l,boolean win){if(!l.e.finish(win,Instant.now().getEpochSecond()))return;ledger.settle(l.e,l.boss.win(config.rewards),l.boss.loss(config.rewards),config.rewards.minimumDamageFraction,config.rewards.minimumParticipationSeconds);save();if(win)cosmicLoot(l);broadcast(l.boss.name+(win?" defeated!":" escaped. Encounter lost.")+" Qualified participants: "+l.e.rewards(l.boss.win(config.rewards),l.boss.loss(config.rewards),config.rewards.minimumDamageFraction,config.rewards.minimumParticipationSeconds).size());cleanup(l);for(var p:server.getPlayerManager().getPlayerList())deliver(p);}
 private void cosmicLoot(Live l){
  var random=l.world.random;var stones=l.boss.stoneDrops.isEmpty()?java.util.List.of(InfinityRules.guardianStone(l.boss.classId)):l.boss.stoneDrops;
  if(random.nextDouble()<l.boss.stoneDropChance)drop(l,stones.get(random.nextInt(stones.size())));
  if(random.nextDouble()<l.boss.gauntletDropChance)drop(l,"gauntlet");
 }
 private void drop(Live l,String item){var value=vn.svframe.fantasyhub.protocol.Protocol.infinityItems.get(item);if(value==null)return;var at=l.center();var drop=new net.minecraft.entity.ItemEntity(l.world,at.x,at.y+1,at.z,new net.minecraft.item.ItemStack(value));drop.setToDefaultPickupDelay();l.world.spawnEntity(drop);broadcast(l.boss.name+" dropped "+item+"!");}
 private void abort(Live l,String reason){l.e.abort();save();cleanup(l);LOG.info("Encounter {} aborted: {} (no rewards)",l.e.id,reason);}
 private void cleanup(Live l){live.remove(l.arena.id);l.bar.clearPlayers();if(l.cosmic!=null)l.cosmic.close();if(l.actor!=null){InfinityRuntime.mitigation.remove(l.actor.getUuid());previousHealth.remove(l.actor.getUuid());l.actor.discard();}if(l.forced){var pos=BlockPos.ofFloored(l.center());l.world.setChunkForced(pos.getX()>>4,pos.getZ()>>4,false);l.e.forcedChunk=false;save();}}
 private void deliver(ServerPlayerEntity p){for(var reward:ledger.pending(p.getUuid())){String key=reward.encounter+":"+p.getUuid();if(!delivering.add(key))continue;ClassProgression.awardSigilsOnce(p,reward.encounter,reward.amount).whenComplete((granted,error)->{var s=server;if(s==null){delivering.remove(key);return;}s.execute(()->{try{if(error!=null){LOG.error("Reward remains in mailbox {}",key,error);return;}ledger.delivered(reward.encounter,p.getUuid());save();if(Boolean.TRUE.equals(granted))p.sendMessage(Text.literal("World boss reward: +"+reward.amount+" Class Sigil banked. Inventory space is not required."),false);}finally{delivering.remove(key);}});});}}
 private String name(UUID id){var p=server.getPlayerManager().getPlayer(id);return p==null?id.toString():p.getName().getString();}
 private void broadcast(String text){server.getPlayerManager().broadcast(Text.literal("[World Boss] "+text),false);}
 private int info(net.minecraft.server.command.ServerCommandSource source){if(server==null){source.sendError(Text.literal("World boss unavailable"));return 0;}source.sendFeedback(()->Text.literal("Next slot: "+schedule.next(Instant.now())+" | active: "+live.size()+" | /worldboss top, mailbox, claim"),false);for(var a:config.locations.locations)source.sendFeedback(()->Text.literal(a.id+" "+a.dimension+" "+Math.round(a.x)+" "+Math.round(a.y)+" "+Math.round(a.z)+" /worldboss join "+a.id),false);for(var l:live.values())source.sendFeedback(()->Text.literal(l.e.id+" "+l.boss.id+" "+l.e.state+" "+l.e.contributions.size()+" participants | "+attackStatus(l,Instant.now().getEpochSecond())),false);return 1;}
 private void audit(String event,Live l,Entity victim,double damage){
  if(!QA)return;try{var path=java.nio.file.Path.of("qa/worldboss/events.jsonl");java.nio.file.Files.createDirectories(path.getParent());var row=new LinkedHashMap<String,Object>();row.put("timeMs",System.currentTimeMillis());row.put("serverTick",server.getTicks());row.put("event",event);row.put("encounter",l.e.id);row.put("boss",l.boss.id);row.put("actor",l.actor==null?"":l.actor.getUuidAsString());row.put("status",attackStatus(l,Instant.now().getEpochSecond()));if(victim!=null){row.put("victim",victim.getUuidAsString());row.put("damage",damage);if(victim instanceof LivingEntity living)row.put("health",living.getHealth());}java.nio.file.Files.writeString(path,new com.google.gson.Gson().toJson(row)+"\n",java.nio.file.StandardOpenOption.CREATE,java.nio.file.StandardOpenOption.APPEND);}catch(java.io.IOException ex){LOG.warn("Could not write opt-in QA combat observation",ex);}
 }
 private void save(){try{ledger.save();}catch(java.io.IOException ex){throw new IllegalStateException("World boss journal save failed",ex);}}
}
